// MOCK QUEUE - swap this node for your real helpdesk node (Jira, Zendesk, or Plain via HTTP Request)
const now = Date.now();
const hrs = h => new Date(now - h * 3600 * 1000).toISOString();
return [
  { json: { id: 'T-1041', subject: 'SSO login loop after IdP cert rotation', customer: 'Acme Corp', arr: 240000, priority: 'urgent', createdAt: hrs(0.8) } },
  { json: { id: 'T-1042', subject: 'Webhook retries failing on workflow 88', customer: 'Globex', arr: 96000, priority: 'high', createdAt: hrs(3.4) } },
  { json: { id: 'T-1043', subject: 'How to bulk-export execution logs', customer: 'Initech', arr: 18000, priority: 'normal', createdAt: hrs(6) } },
  { json: { id: 'T-1044', subject: 'API rate limits on paid plan unclear', customer: 'Umbrella', arr: 54000, priority: 'high', createdAt: hrs(1.1) } }
];

// SLA targets by priority (hours to resolution commitment)
const SLA = { urgent: 1, high: 4, normal: 24 };
const out = [];
for (const item of $input.all()) {
  const t = item.json;
  const target = SLA[t.priority] ?? 24;
  const elapsed = (Date.now() - new Date(t.createdAt).getTime()) / 3600000;
  const pctUsed = Math.round((elapsed / target) * 100);
  let level = null;
  if (pctUsed >= 90) level = 'BREACH IMMINENT';
  else if (pctUsed >= 75) level = 'AT RISK';
  if (level) out.push({ json: { ...t, target, elapsedHrs: +elapsed.toFixed(1), pctUsed, level, minutesLeft: Math.max(0, Math.round((target - elapsed) * 60)) } });
}
return out;

const lines = $input.all().map(({ json: t }) =>
  `${t.level === 'BREACH IMMINENT' ? '[BREACH IMMINENT]' : '[AT RISK]'} ${t.id} - ${t.customer} (ARR $${(t.arr/1000).toFixed(0)}K)
  ${t.subject}
  Priority ${t.priority} | SLA ${t.target}h | ${t.pctUsed}% used | ${t.minutesLeft} min left`);
if (lines.length === 0) return [];
return [{ json: { subject: `SLA Sentinel: ${lines.length} ticket(s) need attention`, body: `Proactive SLA check (before breach, not after):

${lines.join('

')}

Rule: a customer having to chase us is a failure.` } }];
